/*
 * services/signalRService.js
 * 
 * إدارة اتصال SignalR مع الـ Backend
 */

import * as SignalR from '@microsoft/signalr';
import { getCurrentUserId } from './authService';

const API_BASE_URL = process.env.REACT_APP_API_BASE_URL || 'http://localhost:5000';

class SignalRService {
  constructor() {
    this.connection = null;
    this.isConnected = false;
    this.messageCallbacks = [];
    this.connectionStatusCallbacks = [];
  }

  /**
   * بدء اتصال SignalR مع الـ Backend
   */
  async connect() {
    try {
      if (this.isConnected) {
        console.log('✓ اتصال SignalR موجود بالفعل');
        return;
      }

      const userId = getCurrentUserId();
      if (!userId) {
        console.error('❌ لا يوجد معرف مستخدم - لا يمكن الاتصال');
        return;
      }

      console.log(`🔌 محاولة الاتصال بـ SignalR للمستخدم ${userId}...`);

      // إنشاء الاتصال
      this.connection = new SignalR.HubConnectionBuilder()
        .withUrl(`${API_BASE_URL}/chatHub`, {
          withCredentials: true
        })
        .withAutomaticReconnect([0, 1000, 5000, 10000])
        .withHubProtocol(new SignalR.JsonHubProtocol())
        .configureLogging(SignalR.LogLevel.Information)
        .build();

      // استقبال الرسائل الجديدة من الـ Backend
      this.connection.on('ReceiveMessage', (message) => {
        console.log('📨 رسالة جديدة من Backend:', message);
        this.messageCallbacks.forEach(callback => {
          try {
            callback(message);
          } catch (err) {
            console.error('❌ خطأ في معالج الرسالة:', err);
          }
        });
      });

      // معالجة انقطاع الاتصال
      this.connection.onclose((error) => {
        console.log('❌ انقطع الاتصال:', error);
        this.isConnected = false;
        this.notifyConnectionStatus(false);
      });

      // معالجة إعادة الاتصال
      this.connection.onreconnected(() => {
        console.log('✓ تم إعادة الاتصال');
        this.isConnected = true;
        this.registerUser();
        this.notifyConnectionStatus(true);
      });

      // بدء الاتصال
      await this.connection.start();
      console.log('✓ تم الاتصال بـ SignalR بنجاح');
      this.isConnected = true;

      // تسجيل المستخدم الحالي
      await this.registerUser();

      this.notifyConnectionStatus(true);
    } catch (error) {
      console.error('❌ خطأ في الاتصال بـ SignalR:', error);
      this.isConnected = false;
      this.notifyConnectionStatus(false);
    }
  }

  /**
   * قطع الاتصال
   */
  async disconnect() {
    if (this.connection) {
      try {
        await this.connection.stop();
        console.log('✓ تم قطع الاتصال');
        this.isConnected = false;
        this.notifyConnectionStatus(false);
      } catch (error) {
        console.error('❌ خطأ في قطع الاتصال:', error);
      }
    }
  }

  /**
   * تسجيل المستخدم الحالي
   */
  async registerUser() {
    const userId = getCurrentUserId();
    if (userId && this.connection) {
      try {
        await this.connection.invoke('RegisterUser', Number(userId));
        console.log(`✓ تم تسجيل المستخدم ${userId}`);
      } catch (error) {
        console.error('❌ خطأ في تسجيل المستخدم:', error);
      }
    }
  }

  /**
   * الاستماع لرسائل جديدة
   */
  onReceiveMessage(callback) {
    this.messageCallbacks.push(callback);
  }

  /**
   * إزالة الاستماع
   */
  offReceiveMessage(callback) {
    this.messageCallbacks = this.messageCallbacks.filter(cb => cb !== callback);
  }

  /**
   * الاستماع لتغييرات حالة الاتصال
   */
  onConnectionStatusChanged(callback) {
    this.connectionStatusCallbacks.push(callback);
  }

  /**
   * إزالة الاستماع لحالة الاتصال
   */
  offConnectionStatusChanged(callback) {
    this.connectionStatusCallbacks = this.connectionStatusCallbacks.filter(cb => cb !== callback);
  }

  /**
   * إخطار جميع المستمعين بتغيير حالة الاتصال
   */
  notifyConnectionStatus(isConnected) {
    this.connectionStatusCallbacks.forEach(callback => callback(isConnected));
  }

  /**
   * الحصول على حالة الاتصال
   */
  getIsConnected() {
    return this.isConnected;
  }
}

// إنشاء instance واحد من الخدمة
export default new SignalRService();
